bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import {readFileSync} from 'node:fs';import {setDefaultResultOrder} from 'node:dns';import {setDefaultAutoSelectFamily} from 'node:net';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const out=createCreatorTelegramFetch(),e=process.env;
try{
 const token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
 const response=await out.fetch((e.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org')+'/bot'+token+'/getChatMember',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({chat_id:-1002373696859,user_id:788044853}),signal:AbortSignal.timeout(30000)});
 const j=await response.json();
 if(j?.ok!==true)process.exitCode=61;
 else if(j.result?.status==='creator')process.exitCode=71;
 else if(j.result?.status==='administrator')process.exitCode=72;
 else if(j.result?.status==='member')process.exitCode=73;
 else process.exitCode=74;
}catch{process.exitCode=79}finally{await out.close()}
JS
